	private static void assertDiskBackedDistinct(List<BindingSet> rows, List<BindingSet> expected) {
		var step = LmdbPartitionedDistinctSteps
				.partitioned(ignored -> new CloseableIteratorIteration<>(rows.iterator()), "s",
						() -> new MapDb3CollectionFactory(1));
		for (int i = 0; i < 2; i++) {
			try (var result = step.evaluate(EmptyBindingSet.getInstance())) {
				assertThat(Iterations.asList(result)).containsExactlyElementsOf(expected);
			}
		}
	}

	private static List<BindingSet> aliasedRows(IRI subject, int count) {
		List<BindingSet> rows = new ArrayList<>();
		for (int i = 0; i < count; i++) {
			Value value = VF.createIRI("urn:value:" + i);
			MapBindingSet row = new MapBindingSet();
			row.addBinding("s", subject);
			row.addBinding("v", value);
			row.addBinding("w", value);
			rows.add(row);
			rows.add(new QueryBindingSet(row));
		}
		return rows;
	}

	@Test
	void closesOpenedChildAndFactoryWhenMembershipSetupFails() {
		var setupFailure = new IllegalStateException("setup");
		var childCloseFailure = new IllegalStateException("child close");
		var factoryCloseFailure = new IllegalStateException("factory close");
		var child = new CloseableIteratorIteration<BindingSet>(List.of(EmptyBindingSet.getInstance()).iterator()) {
			@Override
			protected void handleClose() {
				throw childCloseFailure;
			}
		};
		var factory = new DefaultCollectionFactory() {
			@Override
			public <T> Set<T> createSet() {
				throw setupFailure;
			}

			@Override
			public Set<BindingSet> createSetOfBindingSets() {
				throw setupFailure;
			}

			@Override
			public void close() {
				throw factoryCloseFailure;
			}
		};

		Throwable thrown = catchThrowable(() -> LmdbPartitionedDistinctSteps
				.partitioned(ignored -> child, "s", () -> factory)
				.evaluate(EmptyBindingSet.getInstance()));

		assertThat(thrown).isSameAs(setupFailure);
		assertThat(child.isClosed()).isTrue();
		assertThat(thrown.getSuppressed()).containsExactly(childCloseFailure, factoryCloseFailure);
	}

	@ParameterizedTest
	@EnumSource(PullFailureSite.class)
	void closesChildAndFactoryWhenPullFails(PullFailureSite failureSite) {
		var pullFailure = new IllegalStateException("pull failed");
		var childCloseFailure = new IllegalStateException("child close failed");
		var factoryCloseFailure = new IllegalStateException("factory close failed");
		BindingSet row = EmptyBindingSet.getInstance();
		var child = new CloseableIteratorIteration<BindingSet>(List.of(row, row).iterator()) {
			private boolean emittedFirst;

			@Override
			public boolean hasNext() {
				if (emittedFirst && failureSite == PullFailureSite.CHILD_HAS_NEXT) {
					throw pullFailure;
				}
				return super.hasNext();
			}

			@Override
			public BindingSet next() {
				if (emittedFirst && failureSite == PullFailureSite.CHILD_NEXT) {
					throw pullFailure;
				}
				emittedFirst = true;
				return super.next();
			}

			@Override
			protected void handleClose() {
				throw childCloseFailure;
			}
		};
		var factory = new DefaultCollectionFactory() {
			private boolean closed;

			@Override
			public <T> Set<T> createSet() {
				return new HashSet<>() {
					@Override
					public boolean add(T value) {
						if (!isEmpty() && failureSite == PullFailureSite.MEMBERSHIP_ADD) {
							throw pullFailure;
						}
						return super.add(value);
					}
				};
			}

			@Override
			public void close() {
				closed = true;
				throw factoryCloseFailure;
			}
		};

		try (var result = LmdbPartitionedDistinctSteps
				.partitioned(ignored -> child, "s", () -> factory)
				.evaluate(EmptyBindingSet.getInstance())) {
			assertThat(result.next()).isSameAs(row);
			Throwable thrown = failureSite == PullFailureSite.CHILD_NEXT
					? catchThrowable(result::next)
					: catchThrowable(result::hasNext);

			assertThat(thrown).isSameAs(pullFailure);
			assertThat(child.isClosed()).isTrue();
			assertThat(factory.closed).isTrue();
			assertThat(thrown.getSuppressed()).containsExactly(childCloseFailure, factoryCloseFailure);
		}
	}

	private enum PullFailureSite {
		CHILD_HAS_NEXT,
		CHILD_NEXT,
		MEMBERSHIP_ADD
	}

	@ParameterizedTest(name = "indexed={0}, criticalPressure={1}")
	@CsvSource({ "false, false", "false, true", "true, false", "true, true" })
	void distinctHonorsCircuitBreakerDuringPulls(boolean indexed, boolean criticalPressure) {
		String query = indexed ? "SELECT DISTINCT ?a ?b WHERE { ?a <urn:p> ?b }"
				: "SELECT DISTINCT ?a ?b WHERE { ?a <urn:p> ?b . ?b <urn:q> ?v }";
		LmdbStore store = openStore(false, "psoc,posc");
		try (var connection = store.getConnection()) {
			loadAliasedValues(connection);
			long partitionsBefore = LmdbPartitionedDistinctSteps.partitionedEvaluationCount();
			long cursorsBefore = LmdbPrefixRunPlan.OPENED.get();
			try (var result = connection.evaluate(parse(query), null, EmptyBindingSet.getInstance(), false)) {
				assertThat(LmdbPartitionedDistinctSteps.partitionedEvaluationCount() - partitionsBefore)
						.isEqualTo(indexed ? 0L : 1L);
				assertThat(LmdbPrefixRunPlan.OPENED.get()).isEqualTo(cursorsBefore);

				QueryCircuitBreaker breaker = QueryCircuitBreaker.getInstance();
				QueryCircuitBreakerHandle handle = breaker.register(QueryCircuitBreakerHandle.Source.SERVER, "test",
						query);
				String previousCriticalThreshold = System.setProperty(QueryCircuitBreaker.CRITICAL_FREE_MB_PROPERTY,
						Integer.toString(Integer.MAX_VALUE));
				String previousEnabled = System.setProperty(QueryCircuitBreaker.ENABLED_PROPERTY,
						Boolean.toString(criticalPressure));
				try (var ignored = QueryExecutionContext.activate(handle)) {
					assertThat(breaker.snapshotStatus().getState()).isEqualTo(criticalPressure ? "CRITICAL" : "NORMAL");
					if (criticalPressure) {
						assertThat(catchThrowable(result::hasNext)).isInstanceOf(QueryInterruptedException.class)
								.hasMessageContaining("Query cancelled by global memory circuit breaker");
						assertThat(handle.isCancelRequested()).isTrue();
					} else {
						assertThat(Iterations.asList(result)).extracting(row -> row.getValue("b"))
								.containsExactlyInAnyOrder(VF.createIRI("urn:b0"), VF.createIRI("urn:b1"),
										VF.createIRI("urn:b2"));
					}
					assertThat(LmdbPrefixRunPlan.OPENED.get() - cursorsBefore).isEqualTo(indexed ? 1L : 0L);
					assertThat(handle.getLastHeavyOperator()).isEqualTo("DISTINCT");
					assertThat(handle.hasHeavyCheckpoint()).isTrue();
				} finally {
					breaker.complete(handle);
					restoreProperty(QueryCircuitBreaker.CRITICAL_FREE_MB_PROPERTY, previousCriticalThreshold);
					// Reset the forced pressure state immediately, including when the breaker was already enabled.
					System.setProperty(QueryCircuitBreaker.ENABLED_PROPERTY, "false");
					breaker.snapshotStatus();
					restoreProperty(QueryCircuitBreaker.ENABLED_PROPERTY, previousEnabled);
					breaker.snapshotStatus();
				}
			}
		} finally {
			store.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void explicitReducedUsesNoPartitionedSet(boolean nativeFactory) {
		String prior = System.setProperty(NATIVE_ENGINE, "false");
		try {
			LmdbStore store = openStore(nativeFactory);
			try (var connection = store.getConnection()) {
				loadAliasedValues(connection);
				TupleExpr query = parse("SELECT REDUCED ?a ?v WHERE { ?a <urn:p> ?b . ?b <urn:q> ?v }");
				long before = LmdbPartitionedDistinctSteps.partitionedEvaluationCount();
				assertThat(evaluate(connection, query)).extracting(row -> row.getValue("v"))
						.contains(VF.createIRI("urn:v1"), VF.createIRI("urn:v2"));
				assertThat(LmdbPartitionedDistinctSteps.partitionedEvaluationCount()).isEqualTo(before);
				assertThat(connection.explain(Explanation.Level.Optimized, query, null,
						EmptyBindingSet.getInstance(), false, 0).toString())
								.contains("Reduced")
								.doesNotContain("statementOrder");
			} finally {
				store.shutDown();
			}
		} finally {
			restoreProperty(NATIVE_ENGINE, prior);
		}
	}

	private static void restoreProperty(String name, String previous) {
		if (previous == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, previous);
		}
	}

